mapper.select:
SELECT event_id,revision,created_at AS occurred_at FROM interview_event_history
WHERE owner_id=#{owner} AND action='COMPLETED' AND created_at>=#{from} AND created_at<#{until}

  AND (created_at<#{after.occurredAt}
    OR (created_at=#{after.occurredAt} AND event_id>#{after.eventId})
    OR (created_at=#{after.occurredAt} AND event_id=#{after.eventId} AND revision>#{after.revision}))

ORDER BY created_at DESC,event_id ASC,revision ASC LIMIT #{limit}
